using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;

namespace Xamarin.Forms.Platform.GTK.UnitTests
{
	/// <summary>
	/// Custom test entry point (<c>XunitAutoGeneratedEntryPoint</c> is disabled in the csproj).
	/// </summary>
	/// <remarks>
	/// It reproduces xUnit v3's generated entry point - the Microsoft Testing Platform path that
	/// <c>dotnet test</c>, Visual Studio and the MSBuild node use, and the console runner otherwise -
	/// and adds a thread-0 path for macOS. GTK 4's only macOS GDK backend is Quartz, which requires
	/// GTK to run on the process's first thread (see <see cref="GtkThreadBridge"/>); scripts/ci/
	/// test-macos.sh runs this assembly directly (<c>dotnet exec</c>) so the console path is taken and
	/// GTK runs on thread 0. Windows and Linux keep using <c>dotnet test</c>, which takes the
	/// unchanged Testing Platform path below, so their behaviour is identical to the generated entry.
	/// </remarks>
	static class Program
	{
		const int WatchdogSeconds = 600;

		[STAThread]
		static int Main(string[] args)
		{
			// dotnet test / Visual Studio / the MSBuild test node drive the Microsoft Testing Platform
			// protocol. Keep this path identical to the generated entry point so the Windows and Linux
			// CI jobs are unaffected by the custom entry.
			if (args.Any(a => a == "--server" || a == "--internal-msbuild-node"))
				return global::Xunit.MicrosoftTestingPlatform.TestPlatformTestFramework
					.RunAsync(args, SelfRegisteredExtensions.AddSelfRegisteredExtensions)
					.GetAwaiter().GetResult();

			bool threadZero = OperatingSystem.IsMacOS()
				|| Environment.GetEnvironmentVariable("XF_GTK_MAC_RUNNER") == "1";

			if (!threadZero)
				return global::Xunit.Runner.InProc.SystemConsole.ConsoleRunner.Run(args).GetAwaiter().GetResult();

			return RunOnThreadZero(args);
		}

		/// <summary>
		/// Owns thread 0 (this thread), runs xUnit on a background thread, and drains the GTK work queue
		/// <see cref="GtkFixture"/> marshals onto - so every GTK call happens on thread 0, as Quartz
		/// requires.
		/// </summary>
		static int RunOnThreadZero(string[] args)
		{
			GtkThreadBridge.Queue = new BlockingCollection<Action>();

			int exit = 0;
			var finished = new ManualResetEventSlim();

			var worker = new Thread(() =>
			{
				try
				{
					exit = global::Xunit.Runner.InProc.SystemConsole.ConsoleRunner.Run(args).GetAwaiter().GetResult();
				}
				catch (Exception e)
				{
					Console.Error.WriteLine("MacRunner: the test runner crashed: " + e);
					exit = 1;
				}
				finally
				{
					// Ends RunLoop on thread 0 so the process can exit.
					GtkThreadBridge.Queue.CompleteAdding();
					finished.Set();
				}
			})
			{ IsBackground = true, Name = "xunit" };

			worker.Start();
			StartWatchdog(finished);

			// Drains GTK work on thread 0 until the worker completes the queue.
			GtkThreadBridge.RunLoop();
			finished.Wait();

			return exit;
		}

		/// <summary>
		/// A test that wedges thread 0 (a modal that never returns on headless macOS, say) would
		/// otherwise hang until the CI job's wall-clock timeout. Fail fast with a named cause instead.
		/// </summary>
		static void StartWatchdog(ManualResetEventSlim finished)
		{
			var watchdog = new Thread(() =>
			{
				if (finished.Wait(TimeSpan.FromSeconds(WatchdogSeconds)))
					return;

				Console.Error.WriteLine(
					$"MacRunner STALL: the GTK test run made no progress for {WatchdogSeconds}s and is " +
					"blocking thread 0; aborting. A test likely opens a modal that never returns on " +
					"headless macOS.");
				Console.Out.Flush();
				Console.Error.Flush();
				Environment.Exit(3);
			})
			{ IsBackground = true, Name = "watchdog" };

			watchdog.Start();
		}
	}
}
